<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Employer,EmployerApprenticeGrant as Grant};
use App\Support\{EmployerSetup as Setup,EmployerActions,AccountOnboarding};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Notification};
use Illuminate\Validation\ValidationException;
use Symfony\Component\HttpKernel\Exception\HttpException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class EmployerSetupTest extends TestCase {
 use LazilyRefreshDatabase,\Tests\Concerns\ConfiguresStaging;
 private function fixture():array {$m=User::factory()->create(['role'=>'admin']);$u=User::factory()->create(['role'=>'employer','name'=>'Fictional Contact']);$e=Employer::factory()->create();$a=Apprentice::factory()->create(['employer_id'=>$e->id,'first_name'=>'VISIBLE-FICTIONAL','last_name'=>'Person','email'=>'PRIVATE-APPRENTICE@example.test']);$g=EmployerActions::grant($m,1,$a,['user_id'=>$u->id,'version'=>0,'identity_reference'=>'PRIVATE-AUTHORITY-REFERENCE']);return [$m,$u,$e,$a,$g];}
 private function data(User $u,array $extra=[]):array {return [...['record_version'=>$u->record_version,'name'=>$u->name,'email'=>$u->email,'active'=>$u->active,'reason'=>'PRIVATE-CONTACT-CHECK-REFERENCE','confirmed'=>1],...$extra];}
 private function checkData(User $u,int $version=0):array {return ['version'=>$version,'scope_hash'=>Setup::scope($u)['hash'],'confirmed'=>1];}
 private function url(User $u):string {return '/employer-accounts/'.$u->id.'/setup';}
 private function token(User $m,User $u,string $purpose='employer_invite'):void {DB::table('account_onboarding_tokens')->insert(['user_id'=>$u->id,'purpose'=>$purpose,'token_hash'=>hash('sha256',str_repeat('t',64)),'auth_version'=>$u->auth_version,'issuer_id'=>$m->id,'issuer_auth_version'=>$m->auth_version,'created_at'=>now(),'expires_at'=>now()->addHour()]);}
 public function test_existing_accounts_route_has_search_setup_and_no_private_authority_source():void {[$m,$u,$e,$a,$g]=$this->fixture();$this->actingAs($m)->get('/employer-accounts?search=Fictional&state=active')->assertOk()->assertSee('Check setup and access')->assertSee($u->email)->assertDontSee('PRIVATE-AUTHORITY')->assertDontSee($u->password)->assertHeader('Referrer-Policy','no-referrer');$this->get($this->url($u))->assertOk()->assertSee('Current workplace authority')->assertSee($a->reference)->assertDontSee('PRIVATE-AUTHORITY');}
 public function test_search_escapes_wildcards_and_paginates_without_scanning_other_roles():void {[$m,$u]=$this->fixture();User::factory()->count(22)->create(['role'=>'employer','name'=>'Other Contact']);User::factory()->create(['role'=>'tutor','name'=>'PRIVATE-STAFF-NAME']);$this->actingAs($m)->get('/employer-accounts?search=%25')->assertOk()->assertSee('0 matching contacts')->assertDontSee($u->email);$this->get('/employer-accounts?search=Other&page=2')->assertOk()->assertSee('22 matching contacts')->assertDontSee('PRIVATE-STAFF-NAME');}
 public function test_account_filters_and_malformed_filters_are_checked():void {[$m,$u]=$this->fixture();$u->active=false;$u->save();$this->actingAs($m)->get('/employer-accounts?state=inactive')->assertSee($u->email);$this->get('/employer-accounts?state=active')->assertDontSee($u->email);$this->get('/employer-accounts?state=unconfirmed')->assertDontSee($u->email);$this->get('/employer-accounts?state=invalid')->assertSessionHasErrors('state');$this->get('/employer-accounts?page=0')->assertSessionHasErrors('page');}
 public function test_non_managers_cannot_view_or_mutate_contact_centre():void {[$m,$u]=$this->fixture();foreach(['employer','apprentice','tutor','mentor','staff','inclusion_lead','careers_adviser']as$role){$x=User::factory()->create(['role'=>$role]);$this->actingAs($x)->get('/employer-accounts')->assertForbidden();$this->get($this->url($u))->assertForbidden();$this->post($this->url($u),[])->assertForbidden();$this->post('/employer-accounts/'.$u->id.'/revoke-invitation',[])->assertForbidden();}}
 public function test_wrong_target_roles_are_not_convertible_by_setup_route():void {[$m,$u]=$this->fixture();$x=User::factory()->create(['role'=>'tutor']);$this->actingAs($m)->get($this->url($x))->assertNotFound();$this->post($this->url($x),$this->data($x))->assertNotFound();$this->assertSame('tutor',$x->fresh()->role);}
 public function test_contact_name_edit_invalidates_sessions_tokens_and_all_grants_without_exposing_reason():void {[$m,$u,$e,$a,$g]=$this->fixture();$this->token($m,$u);Notification::fake();$password=$u->password;$this->actingAs($m)->post($this->url($u),$this->data($u,['name'=>'Fictional Corrected']))->assertSessionHasNoErrors();$u->refresh();$this->assertSame(2,$u->auth_version);$this->assertSame(2,$u->record_version);$this->assertSame($password,$u->password);$this->assertSame('employer',$u->role);$this->assertNotNull($u->email_verified_at);$this->assertFalse($g->fresh()->active);$this->assertSame(2,$g->fresh()->version);$this->assertDatabaseCount('account_onboarding_tokens',0);$raw=DB::table('employer_start_events')->value('payload');$this->assertStringNotContainsString('PRIVATE-CONTACT',$raw);$this->assertStringContainsString('PRIVATE-CONTACT',Crypt::decryptString($raw));$this->get($this->url($u))->assertDontSee('PRIVATE-CONTACT');Notification::assertNothingSent();}
 public function test_email_edit_normalises_and_unconfirms_mailbox():void {[$m,$u]=$this->fixture();$this->actingAs($m)->post($this->url($u),$this->data($u,['email'=>'CORRECTED@example.test']))->assertSessionHasNoErrors();$this->assertSame('corrected@example.test',$u->fresh()->email);$this->assertNull($u->fresh()->email_verified_at);}
 public function test_deactivation_then_reactivation_never_restores_old_workplace_access():void {[$m,$u,$e,$a,$g]=$this->fixture();$this->actingAs($m)->post($this->url($u),$this->data($u,['active'=>0]))->assertSessionHasNoErrors();$this->assertFalse($u->fresh()->active);$this->assertFalse($g->fresh()->active);$this->post($this->url($u),$this->data($u->fresh(),['active'=>1]))->assertSessionHasNoErrors();$this->assertTrue($u->fresh()->active);$this->assertFalse(EmployerActions::valid($g->fresh(),$a));$this->assertSame(0,Setup::readiness($u->fresh())['current']);}
 public function test_duplicate_email_cannot_merge_or_change_other_roles():void {[$m,$u]=$this->fixture();$x=User::factory()->create(['role'=>'admin','email'=>'other@example.test']);$this->actingAs($m)->post($this->url($u),$this->data($u,['email'=>'OTHER@example.test']))->assertSessionHasErrors('employer_setup');$this->assertSame(1,$u->fresh()->auth_version);$this->assertSame('admin',$x->fresh()->role);}
 public function test_stale_contact_version_and_missing_confirmations_write_nothing():void {[$m,$u,$e,$a,$g]=$this->fixture();$this->actingAs($m)->post($this->url($u),$this->data($u,['record_version'=>2,'name'=>'Changed']))->assertSessionHasErrors('employer_setup');foreach(['reason','confirmed','active']as$key){$d=$this->data($u);unset($d[$key]);$this->post($this->url($u),$d)->assertSessionHasErrors($key);}$this->assertTrue($g->fresh()->active);$this->assertDatabaseCount('employer_start_events',0);}
 public function test_noop_does_not_invalidate_access_and_role_password_fields_are_ignored():void {[$m,$u,$e,$a,$g]=$this->fixture();$this->actingAs($m)->post($this->url($u),$this->data($u,['role'=>'admin','password'=>'Injected-password']))->assertSessionHasNoErrors();$this->assertSame(1,$u->fresh()->auth_version);$this->assertSame('employer',$u->fresh()->role);$this->assertTrue($g->fresh()->active);$this->assertDatabaseCount('employer_start_events',0);}
 public function test_service_rechecks_actor_activity_role_and_auth_version():void {[$m,$u]=$this->fixture();$m->auth_version=2;$m->save();try{Setup::updateContact($m,1,$u,1,$this->data($u,['name'=>'Changed']));$this->fail('stale actor');}catch(HttpException $x){$this->assertSame(403,$x->getStatusCode());}$m->role='tutor';$m->save();try{Setup::updateContact($m,2,$u,1,$this->data($u,['name'=>'Changed']));$this->fail('wrong actor');}catch(HttpException $x){$this->assertSame(403,$x->getStatusCode());}$this->assertSame('Fictional Contact',$u->fresh()->name);}
 public function test_failed_contact_audit_rolls_back_user_tokens_and_permission_changes():void {[$m,$u,$e,$a,$g]=$this->fixture();$this->token($m,$u);AuditFault::install('employer_contact_fault','employer_start_events','Synthetic audit failure');try{Setup::updateContact($m,1,$u,1,$this->data($u,['name'=>'Changed']));$this->fail('audit failure ignored');}catch(\Illuminate\Database\QueryException){}$this->assertSame(1,$u->fresh()->auth_version);$this->assertTrue($g->fresh()->active);$this->assertDatabaseCount('account_onboarding_tokens',1);}
 public function test_invitation_status_and_revoke_never_expose_token_or_modify_other_token_purposes():void {[$m,$u]=$this->fixture();$u->email_verified_at=null;$u->save();$this->token($m,$u);$this->token($m,$u,'verify');$state=Setup::invitation($u);$this->actingAs($m)->get($this->url($u))->assertOk()->assertDontSee(hash('sha256',str_repeat('t',64)))->assertDontSee(str_repeat('t',64));$this->post('/employer-accounts/'.$u->id.'/revoke-invitation',['record_version'=>1,'stamp'=>$state['stamp'],'confirmed'=>1])->assertSessionHasNoErrors();$this->assertDatabaseMissing('account_onboarding_tokens',['user_id'=>$u->id,'purpose'=>'employer_invite']);$this->assertDatabaseHas('account_onboarding_tokens',['user_id'=>$u->id,'purpose'=>'verify']);$this->assertSame(1,$u->fresh()->auth_version);}
 public function test_revoke_refuses_replaced_token_and_stale_contact_version():void {[$m,$u]=$this->fixture();$this->token($m,$u);$old=Setup::invitation($u);DB::table('account_onboarding_tokens')->where('user_id',$u->id)->update(['token_hash'=>hash('sha256','new')]);$this->actingAs($m)->post('/employer-accounts/'.$u->id.'/revoke-invitation',['record_version'=>1,'stamp'=>$old['stamp'],'confirmed'=>1])->assertSessionHasErrors('employer_setup');$this->post('/employer-accounts/'.$u->id.'/revoke-invitation',['record_version'=>2,'stamp'=>Setup::invitation($u)['stamp'],'confirmed'=>1])->assertSessionHasErrors('employer_setup');$this->assertDatabaseCount('account_onboarding_tokens',1);}
 public function test_revoke_audit_failure_rolls_back_token_deletion():void {[$m,$u]=$this->fixture();$this->token($m,$u);AuditFault::install('invite_revoke_fault','account_access_events','Synthetic audit failure','employer_invite_revoked');try{Setup::revokeInvitation($m,1,$u,1,Setup::invitation($u)['stamp']);$this->fail('audit failure ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('account_onboarding_tokens',1);}
 public function test_expired_and_changed_issuer_invitation_are_labelled_and_can_be_revoked():void {[$m,$u]=$this->fixture();$this->token($m,$u);$m->auth_version=2;$m->save();$this->assertSame('Account or issuer changed',Setup::invitation($u)['state']);DB::table('account_onboarding_tokens')->update(['expires_at'=>now()->subMinute()]);$this->assertSame('Expired',Setup::invitation($u)['state']);Setup::revokeInvitation($m,2,$u,1,Setup::invitation($u)['stamp']);$this->assertDatabaseCount('account_onboarding_tokens',0);}
 public function test_self_start_only_displays_current_named_authority_not_private_or_other_people():void {[$m,$u,$e,$a,$g]=$this->fixture();$other=Apprentice::factory()->create(['first_name'=>'PRIVATE-OTHER-PERSON']);$this->actingAs($u)->get('/employer-getting-started')->assertOk()->assertSee('VISIBLE-FICTIONAL')->assertDontSee('PRIVATE-OTHER-PERSON')->assertDontSee('PRIVATE-APPRENTICE')->assertDontSee('PRIVATE-AUTHORITY')->assertHeader('Cache-Control','no-store, private');}
 public function test_unverified_or_revoked_contact_sees_no_learner_names_and_cannot_confirm():void {[$m,$u,$e,$a,$g]=$this->fixture();$data=$this->checkData($u);$g->active=false;$g->save();$this->actingAs($u)->get('/employer-getting-started')->assertOk()->assertDontSee('VISIBLE-FICTIONAL')->assertSee('No current apprentice access');$this->post('/employer-getting-started/people-v1',$data)->assertSessionHasErrors('employer_setup');$g->active=true;$g->save();$u->email_verified_at=null;$u->save();$this->actingAs($u)->get('/employer-getting-started')->assertDontSee('VISIBLE-FICTIONAL');$this->assertDatabaseCount('employer_start_checks',0);}
 public function test_only_employer_can_use_self_routes_and_manager_cannot_confirm_for_them():void {[$m,$u]=$this->fixture();foreach(['admin','ceo','apprentice','tutor','staff']as$role){$x=User::factory()->create(['role'=>$role]);$this->actingAs($x)->get('/employer-getting-started')->assertForbidden();$this->post('/employer-getting-started/people-v1',[])->assertForbidden();}}
 public function test_self_confirm_clear_and_encrypted_history_are_informal_only():void {[$m,$u,$e,$a,$g]=$this->fixture();Notification::fake();$before=$a->fresh()->getAttributes();$d=$this->checkData($u);$this->actingAs($u)->post('/employer-getting-started/people-v1',$d)->assertSessionHasNoErrors();$this->assertDatabaseHas('employer_start_checks',['user_id'=>$u->id,'version'=>1,'scope_hash'=>$d['scope_hash']]);$checks=Setup::checks($u,Setup::scope($u));$this->assertNotNull($checks['people-v1']['confirmed_at']);$this->post('/employer-getting-started/people-v1',[...$d,'version'=>1,'confirmed'=>0])->assertSessionHasNoErrors();$this->assertNull(Setup::checks($u,Setup::scope($u))['people-v1']['confirmed_at']);$raw=DB::table('employer_start_events')->value('payload');$this->assertStringNotContainsString('scope_hash',$raw);$this->assertSame('people-v1',json_decode(Crypt::decryptString($raw),true)['item']);$this->assertSame($before,$a->fresh()->getAttributes());$this->assertDatabaseCount('employer_portal_actions',0);Notification::assertNothingSent();}
 public function test_stale_check_and_forged_scope_are_rejected():void {[$m,$u]=$this->fixture();$d=$this->checkData($u);$this->actingAs($u)->post('/employer-getting-started/people-v1',$d)->assertSessionHasNoErrors();$this->post('/employer-getting-started/people-v1',$d)->assertSessionHasErrors('employer_setup');$this->post('/employer-getting-started/actions-v1',[...$d,'scope_hash'=>str_repeat('a',64)])->assertSessionHasErrors('employer_setup');$this->assertDatabaseCount('employer_start_checks',1);}
 public function test_grant_edit_holds_checklist_without_restoring_or_completing_anything():void {[$m,$u,$e,$a,$g]=$this->fixture();$d=$this->checkData($u);$this->actingAs($u)->post('/employer-getting-started/people-v1',$d)->assertSessionHasNoErrors();$g->version++;$g->save();$c=Setup::checks($u,Setup::scope($u));$this->assertNull($c['people-v1']['confirmed_at']);$this->assertTrue((bool)$c['people-v1']['needs_recheck']);$this->post('/employer-getting-started/actions-v1',$d)->assertSessionHasErrors('employer_setup');$this->get('/employer-getting-started')->assertSee('Please check this step again');}
 public function test_changed_apprentice_workplace_or_employer_metadata_removes_self_visibility():void {[$m,$u,$e,$a,$g]=$this->fixture();$e->record_version++;$e->save();$this->assertSame([],Setup::scope($u)['people']);$this->assertContains('Employer record changed',Setup::reasons($g,$a,$u));$e->record_version--;$e->save();$a->employer_id=Employer::factory()->create()->id;$a->save();$this->assertSame([],Setup::scope($u)['people']);$this->assertContains('Apprentice workplace changed or unavailable',Setup::reasons($g,$a,$u));}
 public function test_invalid_item_bad_payload_and_unconfirmed_post_have_no_writes():void {[$m,$u]=$this->fixture();$d=$this->checkData($u);$this->actingAs($u)->post('/employer-getting-started/not-real',$d)->assertNotFound();foreach(['version','scope_hash','confirmed']as$key){$x=$d;unset($x[$key]);$this->post('/employer-getting-started/people-v1',$x)->assertSessionHasErrors($key);}$this->assertDatabaseCount('employer_start_checks',0);}
 public function test_self_service_rechecks_stale_auth_and_inactive_account():void {[$m,$u]=$this->fixture();$scope=Setup::scope($u);$u->auth_version=2;$u->save();try{Setup::saveCheck($u,1,'people-v1',0,$scope['hash'],true);$this->fail('stale actor');}catch(HttpException $x){$this->assertSame(403,$x->getStatusCode());}$u->active=false;$u->save();try{Setup::saveCheck($u,2,'people-v1',0,$scope['hash'],true);$this->fail('inactive actor');}catch(HttpException $x){$this->assertSame(403,$x->getStatusCode());}$this->assertDatabaseCount('employer_start_checks',0);}
 public function test_failed_check_audit_rolls_back_new_confirmation():void {[$m,$u]=$this->fixture();AuditFault::install('employer_check_fault','employer_start_events','Synthetic audit failure');try{Setup::saveCheck($u,1,'people-v1',0,Setup::scope($u)['hash'],true);$this->fail('audit failure ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('employer_start_checks',0);}
 public function test_daily_check_change_limit_stops_churn():void {[$m,$u]=$this->fixture();for($i=0;$i<100;$i++){DB::table('employer_start_events')->insert(['check_id'=>null,'actor_id'=>$u->id,'event'=>'fictional_limit','payload'=>Crypt::encryptString('{}'),'created_at'=>now()]);}try{Setup::saveCheck($u,1,'people-v1',0,Setup::scope($u)['hash'],true);$this->fail('limit ignored');}catch(ValidationException){}$this->assertDatabaseCount('employer_start_checks',0);}
 public function test_multi_workplace_named_grants_only_and_new_authority_requires_fresh_check():void {[$m,$u]=$this->fixture();$old=Setup::scope($u);$a=Apprentice::factory()->create(['employer_id'=>Employer::factory()->create()->id]);EmployerActions::grant($m,1,$a,['user_id'=>$u->id,'version'=>0,'identity_reference'=>'Fictional second named authority']);$new=Setup::scope($u);$this->assertCount(2,$new['people']);$this->assertNotSame($old['hash'],$new['hash']);$this->assertSame(2,Setup::readiness($u)['current']);}
 public function test_get_requests_do_not_write_and_post_only_actions_are_enforced():void {[$m,$u]=$this->fixture();$this->actingAs($m)->get('/employer-accounts')->assertOk();$this->get($this->url($u))->assertOk();$this->get('/employer-accounts/'.$u->id.'/revoke-invitation')->assertStatus(405);$this->actingAs($u)->get('/employer-getting-started')->assertOk();$this->get('/employer-getting-started/people-v1')->assertStatus(405);$this->assertDatabaseCount('employer_start_events',0);$this->assertDatabaseCount('employer_start_checks',0);}
 public function test_revoking_real_issued_invitation_makes_its_link_unusable_without_sending_again():void {[$m,$u]=$this->fixture();$u->email_verified_at=null;$u->save();$this->configureStaging();config(['onboarding.enabled'=>true,'onboarding.recipients'=>[$u->email],'mail.default'=>'smtp','mail.mailers.smtp'=>['transport'=>'smtp','scheme'=>'smtps','host'=>'smtp.example.test','port'=>465,'timeout'=>10],'mail.from.address'=>'portal@example.test']);Notification::fake();DB::transaction(fn()=>AccountOnboarding::issue($u,'employer_invite',$m));$link=Notification::sent($u,\App\Notifications\AccountOnboardingLink::class)->last()->link;$token=basename($link);$this->assertTrue(AccountOnboarding::valid($u,'employer_invite',$token));$this->assertSame('Link prepared; delivery not guaranteed',Setup::invitation($u)['state']);Setup::revokeInvitation($m,1,$u,1,Setup::invitation($u)['stamp']);$this->assertFalse(AccountOnboarding::valid($u,'employer_invite',$token));$this->get($link)->assertForbidden();Notification::assertSentTimes(\App\Notifications\AccountOnboardingLink::class,1);}

}
